select ,
       (select count(1) from sdsshop.u_m_buyer2 b2
         where b2.shop_code = b.shop_code and b2.buyercode = b.buyercode) buyer2_count
  from sdsshop.u_m_buyer b
 where shop_code = #{query.shopCode}

  and buyercode like concat('%', #{query.buyerCode}, '%')


  and (buyersimple like concat('%', #{query.buyerSimple}, '%')
    or buyerfull like concat('%', #{query.buyerSimple}, '%'))

  and mobile like concat('%', #{query.mobile}, '%')

  and contactperson like concat('%', #{query.contactPerson}, '%')

  and staffcode = #{query.staffCode}

  and buyertype = #{query.buyerType}

  and starrating = #{query.starRating}

  and activeflag = #{query.activeFlag}
 order by activeflag desc, createtime desc, buyercode desc

