  from sdsshop.u_m_buyer
 where shop_code = #{shopCode} and buyercode = #{buyerCode}

select 
  from sdsshop.u_m_buyer
 where shop_code = #{shopCode}
   and mobile = #{mobile}
   and #{mobile} is not null
 limit 1

